CREATE TABLE IF NOT EXISTS "users" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"email" VARCHAR(255) NOT NULL UNIQUE,
	"password_hash" VARCHAR(255) NOT NULL,
	"role" VARCHAR(255) NOT NULL DEFAULT 'visitor' CHECK(role IN ('visitor', 'restaurant', 'admin')),
	"preferred_language" VARCHAR(10) NOT NULL DEFAULT 'vi' CHECK(preferred_language IN ('vi', 'en', 'es', 'zh', 'ko', 'ja')),
	"is_active" BOOLEAN NOT NULL DEFAULT TRUE,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "restaurants" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"owner_id" INTEGER NOT NULL,
	"name" VARCHAR(255) NOT NULL,
	"description" TEXT,
	"phone" VARCHAR(20) NOT NULL,
	"status" VARCHAR(255) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected')),
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "poi_categories" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"slug" VARCHAR(255) NOT NULL UNIQUE,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "pois" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"restaurant_id" INTEGER NOT NULL,
	"category_id" INTEGER NOT NULL,
	"title" VARCHAR(255) NOT NULL,
	"description" TEXT,
	"latitude" DOUBLE PRECISION NOT NULL,
	"longitude" DOUBLE PRECISION NOT NULL,
	"price_min" NUMERIC(10, 0),
	"price_max" NUMERIC(10, 0),
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "poi_translations" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"poi_id" INTEGER NOT NULL,
	"language_code" VARCHAR(10) NOT NULL DEFAULT 'vi' CHECK(language_code IN ('vi', 'en', 'es', 'zh', 'ko', 'ja')),
	"title" VARCHAR(255) NOT NULL,
	"description" TEXT,
	"audio_script" TEXT NOT NULL,
	"is_auto_translated" BOOLEAN NOT NULL DEFAULT TRUE,
	"source_language" VARCHAR(10) CHECK(source_language IN ('vi', 'en', 'es', 'zh', 'ko', 'ja')),
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "poi_images" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"poi_id" INTEGER NOT NULL,
	"url" VARCHAR(255) NOT NULL,
	"display_order" INTEGER NOT NULL DEFAULT 0,
	"is_primary" BOOLEAN NOT NULL DEFAULT FALSE,
	"uploaded_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "poi_ratings" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"user_id" INTEGER NOT NULL,
	"poi_id" INTEGER NOT NULL,
	"rating" INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),
	"comment" TEXT,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "tours" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"description" TEXT,
	"estimated_duration_min" INTEGER,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "tour_pois" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"tour_id" INTEGER NOT NULL,
	"poi_id" INTEGER NOT NULL,
	"order_index" INTEGER NOT NULL,
	PRIMARY KEY("id")
);



ALTER TABLE "restaurants"
ADD FOREIGN KEY("owner_id") REFERENCES "users"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "pois"
ADD FOREIGN KEY("restaurant_id") REFERENCES "restaurants"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "pois"
ADD FOREIGN KEY("category_id") REFERENCES "poi_categories"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "poi_translations"
ADD FOREIGN KEY("poi_id") REFERENCES "pois"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "poi_images"
ADD FOREIGN KEY("poi_id") REFERENCES "pois"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "poi_ratings"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "poi_ratings"
ADD FOREIGN KEY("poi_id") REFERENCES "pois"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "tour_pois"
ADD FOREIGN KEY("tour_id") REFERENCES "tours"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "tour_pois"
ADD FOREIGN KEY("poi_id") REFERENCES "pois"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;